CREATE TABLE `users` (`id` VARCHAR(191) NOT NULL, `full_name` VARCHAR(120) NOT NULL, `country_code` VARCHAR(8) NOT NULL DEFAULT '+91', `mobile_number` VARCHAR(20) NOT NULL, `email` VARCHAR(190) NULL, `city` VARCHAR(120) NULL, `locale` VARCHAR(8) NOT NULL DEFAULT 'en', `role` ENUM('CUSTOMER','SALON_OWNER') NOT NULL, `status` ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE', `password_hash` VARCHAR(255) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `users_email_key` (`email`), UNIQUE INDEX `users_country_code_mobile_number_key` (`country_code`,`mobile_number`), INDEX `users_role_status_idx` (`role`,`status`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `salons` (`id` VARCHAR(191) NOT NULL, `owner_id` VARCHAR(191) NOT NULL, `salon_name` VARCHAR(160) NOT NULL, `salon_type` VARCHAR(80) NOT NULL, `contact_number` VARCHAR(24) NOT NULL, `email` VARCHAR(190) NULL, `address` VARCHAR(255) NOT NULL, `city` VARCHAR(120) NOT NULL, `state` VARCHAR(120) NOT NULL, `pincode` VARCHAR(16) NOT NULL, `description` TEXT NULL, `approval_status` ENUM('PENDING','APPROVED','REJECTED','RESTRICTED') NOT NULL DEFAULT 'PENDING', `rejection_reason` TEXT NULL, `approved_at` DATETIME(3) NULL, `trial_starts_at` DATETIME(3) NULL, `trial_ends_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `salons_owner_id_key` (`owner_id`), INDEX `salons_approval_status_city_idx` (`approval_status`,`city`), CONSTRAINT `salons_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `otps` (`id` VARCHAR(191) NOT NULL, `country_code` VARCHAR(8) NOT NULL, `mobile_number` VARCHAR(20) NOT NULL, `purpose` ENUM('LOGIN','REGISTER') NOT NULL, `code_hash` VARCHAR(255) NOT NULL, `expires_at` DATETIME(3) NOT NULL, `verified_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `user_id` VARCHAR(191) NULL, PRIMARY KEY (`id`), INDEX `otps_country_code_mobile_number_purpose_created_at_idx` (`country_code`,`mobile_number`,`purpose`,`created_at`), CONSTRAINT `otps_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `refresh_tokens` (`id` VARCHAR(191) NOT NULL, `token_hash` VARCHAR(255) NOT NULL, `expires_at` DATETIME(3) NOT NULL, `revoked_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `user_id` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `refresh_tokens_token_hash_key` (`token_hash`), INDEX `refresh_tokens_user_id_revoked_at_idx` (`user_id`,`revoked_at`), CONSTRAINT `refresh_tokens_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
